1	#!/usr/bin/env python3
2	"""OpenSurvey HTTP service."""
3	import argparse
4	import json
5	import re
6	from http.server import BaseHTTPRequestHandler, HTTPServer
7	from pathlib import Path
8	import signal
9	import sqlite3
10	from urllib.parse import urlsplit
11	
12	PRODUCT = "OpenSurvey"
13	RESOURCE = "surveys"
14	MAX_BODY_BYTES = 10 * 1024 * 1024
15	QUESTION_TYPES = ("text", "single_choice")
16	
17	PAGE = r"""<!doctype html>
18	<html lang="zh-CN">
19	<meta charset="utf-8">
20	<meta name="viewport" content="width=device-width,initial-scale=1">
21	<title>OpenSurvey · 问卷调查与反馈管理</title>
22	<style>
23	:root{--blue:#175b9c;--red:#c0392b;--grey:#666;--line:#d8dce3}
24	*{box-sizing:border-box}
25	body{font-family:system-ui,"PingFang SC","Microsoft YaHei",sans-serif;max-width:52rem;margin:2.5rem auto;padding:0 1rem;line-height:1.7;color:#1f2430}
26	a{color:var(--blue)}
27	h1{margin-bottom:.2rem}
28	h2{margin-top:2.2rem;border-bottom:1px solid var(--line);padding-bottom:.3rem}
29	.muted{color:var(--grey);font-size:.92rem}
30	ul.plain{list-style:none;padding-left:0}
31	ul.plain li{padding:.25rem 0;border-bottom:1px dashed var(--line)}
32	form label{display:block;margin:1rem 0 .25rem;font-weight:600}
33	input[type=text],textarea,input.opt-text,input.q-title{width:100%;padding:.5rem .6rem;border:1px solid var(--line);border-radius:.35rem;font:inherit}
34	textarea{resize:vertical}
35	.card{border:1px solid var(--line);border-radius:.5rem;padding:1rem 1.2rem;margin:1rem 0;background:#fafbfd}
36	.q-head{display:flex;align-items:center;gap:.7rem;flex-wrap:wrap;margin-bottom:.5rem}
37	.q-index{font-weight:700}
38	.tag{font-size:.8rem;background:#e8f0fa;color:var(--blue);border-radius:1rem;padding:.05rem .6rem}
39	.tag.required{background:#fdecea;color:var(--red)}
40	.req{margin:0;font-weight:400;display:flex;align-items:center;gap:.3rem}
41	.spacer{flex:1}
42	button{font:inherit;cursor:pointer}
43	.btn{border:1px solid var(--blue);background:var(--blue);color:#fff;border-radius:.35rem;padding:.45rem 1.1rem;text-decoration:none;display:inline-block}
44	.btn.secondary{background:#fff;color:var(--blue)}
45	.link{border:none;background:none;color:var(--blue);padding:0;font-size:.92rem}
46	.link.danger{color:var(--red)}
47	.row-actions{display:flex;gap:.8rem;flex-wrap:wrap;margin-top:1.2rem}
48	.opt-row{display:flex;align-items:center;gap:.6rem;margin:.4rem 0}
49	.opt-index{color:var(--grey);font-size:.9rem;min-width:3.2rem}
50	.banner{border:1px solid var(--red);background:#fdf3f2;color:var(--red);border-radius:.5rem;padding:.7rem 1rem;margin:1rem 0;white-space:normal}
51	.banner ul{margin:.4rem 0 0;padding-left:1.2rem}
52	.banner button{color:var(--red);text-decoration:underline;background:none;border:none;padding:0;text-align:left}
53	.field-err{color:var(--red);font-size:.85rem;margin:.25rem 0 0;min-height:1px}
54	.invalid{border-color:var(--red)!important;background:#fdf6f5}
55	.detail-meta{color:var(--grey);font-size:.9rem}
56	.detail-desc,.opt-text-display{white-space:pre-wrap}
57	.q-list>li{margin:1rem 0}
58	.q-list .q-line{font-weight:600}
59	.q-list ol{margin:.4rem 0 0 1.4rem}
60	</style>
61	<main>
62	<h1>OpenSurvey</h1>
63	<p>问卷调查与反馈管理</p>
64	<div id="app"></div>
65	<p class="muted"><a href="/api/surveys">问卷列表接口</a> · <a href="/health">服务状态</a></p>
66	</main>
67	<script>
68	"use strict";
69	const app = document.getElementById("app");
70	
71	// 每次进入一个页面都开启新一代视图：切换首页/详情/编辑、重新进入同一份问卷、
72	// 重试加载以及浏览器前进/后退都会使代数递增。较早一代页面发起的请求再晚
73	// 返回也必须丢弃，不能覆盖用户当前所在页面。
74	let activeView = 0;
75	
76	function h(tag, attrs, ...children) {
77	  const el = document.createElement(tag);
78	  if (attrs) for (const [k, v] of Object.entries(attrs)) {
79	    if (v === null || v === undefined) continue;
80	    if (k === "class") el.className = v;
81	    else if (k.startsWith("on")) el.addEventListener(k.slice(2), v);
82	    else el.setAttribute(k, v);
83	  }
84	  for (const child of children.flat()) {
85	    if (child === null || child === undefined) continue;
86	    el.append(child.nodeType ? child : document.createTextNode(String(child)));
87	  }
88	  return el;
89	}
90	
91	/* ---------- 问卷表单（新建 / 编辑共用） ---------- */
92	
93	function buildSurveyForm(existing, hooks) {
94	  const mode = existing ? "edit" : "create";
95	
96	  const banner = h("div", {class: "banner", id: "form-banner"});
97	  banner.hidden = true;
98	
99	  const titleInput = h("input", {type: "text", id: "survey-title", maxlength: "200", placeholder: "请输入问卷标题"});
100	  const titleErr = h("p", {class: "field-err", id: "title-err"});
101	  const descArea = h("textarea", {id: "survey-desc", rows: "4", placeholder: "问卷说明（可留空，支持中文、引号与换行）"});
102	  const qBox = h("div", {id: "questions"});
103	  const qErr = h("p", {class: "field-err", id: "questions-err"});
104	
105	  function renumber() {
106	    const cards = qBox.querySelectorAll(".q-card");
107	    cards.forEach((card, i) => {
108	      card.querySelector(".q-index").textContent = `第 ${i + 1} 题`;
109	      card.querySelectorAll(".opt-row").forEach((row, j) => {
110	        row.querySelector(".opt-index").textContent = `选项 ${j + 1}`;
111	      });
112	    });
113	  }
114	
115	  function optionRow(value) {
116	    const text = h("input", {type: "text", class: "opt-text", placeholder: "选项内容"});
117	    if (value !== undefined && value !== null) text.value = value;
118	    const row = h("div", {class: "opt-row"},
119	      h("span", {class: "opt-index"}, "选项"),
120	      text,
121	      h("button", {type: "button", class: "link danger", onclick: () => { row.remove(); renumber(); }}, "删除")
122	    );
123	    return row;
124	  }
125	
126	  function addQuestion(type, prefill) {
127	    const isChoice = type === "single_choice";
128	    const options = h("div", {class: "options"});
129	    const card = h("div", {class: "card q-card", "data-type": type},
130	      h("div", {class: "q-head"},
131	        h("span", {class: "q-index"}, "第 N 题"),
132	        h("span", {class: "tag q-type-tag"}, isChoice ? "单选题" : "文本题"),
133	        h("label", {class: "req"},
134	          h("input", {type: "checkbox", class: "q-required"}), "必填（默认非必填）"),
135	        h("span", {class: "spacer"}),
136	        h("button", {type: "button", class: "link danger", onclick: () => { card.remove(); renumber(); }}, "删除本题")
137	      ),
138	      h("input", {type: "text", class: "q-title", placeholder: "题目标题"}),
139	      h("p", {class: "field-err q-title-err"})
140	    );
141	    if (isChoice) {
142	      const saved = prefill && Array.isArray(prefill.options) ? prefill.options : null;
143	      if (saved && saved.length) saved.forEach(value => options.append(optionRow(value)));
144	      else options.append(optionRow(), optionRow());
145	      card.append(
146	        options,
147	        h("p", {class: "field-err opt-err"}),
148	        h("button", {type: "button", class: "link add-opt"}, "添加选项")
149	      );
150	      card.querySelector(".add-opt").addEventListener("click", () => {
151	        options.append(optionRow());
152	        renumber();
153	        options.querySelector(".opt-row:last-child .opt-text").focus();
154	      });
155	    }
156	    if (prefill) {
157	      card.querySelector(".q-title").value = prefill.title != null ? prefill.title : "";
158	      card.querySelector(".q-required").checked = !!prefill.required;
159	    }
160	    qBox.append(card);
161	    renumber();
162	    if (!prefill) card.querySelector(".q-title").focus();
163	    return card;
164	  }
165	
166	  function clearErrors() {
167	    banner.hidden = true;
168	    banner.replaceChildren();
169	    titleErr.textContent = "";
170	    qErr.textContent = "";
171	    qBox.querySelectorAll(".invalid").forEach(el => el.classList.remove("invalid"));
172	    qBox.querySelectorAll(".field-err").forEach(el => { el.textContent = ""; });
173	  }
174	
175	  function showBanner(items) {
176	    banner.replaceChildren(h("strong", null, "问卷未能保存，请修改后重试："), h("ul", null,
177	      items.map(it => h("li", null, h("button", {type: "button", onclick: () => it.el && it.el.focus()}, it.msg)))));
178	    banner.hidden = false;
179	    banner.scrollIntoView({behavior: "smooth", block: "nearest"});
180	  }
181	
182	  const actionButtons = [
183	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("text")}, "添加文本题"),
184	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("single_choice")}, "添加单选题"),
185	    h("span", {class: "spacer"})
186	  ];
187	  if (mode === "edit") {
188	    // 离开编辑页即丢弃全部未保存的增删与输入
189	    actionButtons.push(h("a", {class: "btn secondary", href: `#/surveys/${existing.id}`}, "取消"));
190	  }
191	  actionButtons.push(h("button", {type: "submit", class: "btn"},
192	    mode === "edit" ? "保存修改" : "保存整份问卷"));
193	
194	  const form = h("form", {id: "draft-form", onsubmit: submitForm},
195	    banner,
196	    h("section", null,
197	      h("h2", null, mode === "edit" ? `编辑问卷草稿 #${existing.id}` : "新建问卷草稿"),
198	      mode === "edit"
199	        ? h("p", {class: "muted"}, "保存将整份替换当前草稿；取消则放弃本次修改，问卷编号和地址不变。")
200	        : null,
201	      h("label", {for: "survey-title"}, "标题"),
202	      titleInput, titleErr,
203	      h("label", {for: "survey-desc"}, "说明"),
204	      descArea,
205	      h("label", null, "题目（按下方顺序保存，至少保留一道题）"),
206	      qBox, qErr,
207	      h("div", {class: "row-actions"}, actionButtons)
208	    )
209	  );
210	
211	  if (mode === "edit") {
212	    titleInput.value = existing.title != null ? existing.title : "";
213	    descArea.value = existing.description || "";
214	    existing.questions.forEach(question => addQuestion(question.type, question));
215	    renumber();
216	  }
217	
218	  async function submitForm(event) {
219	    event.preventDefault();
220	    clearErrors();
221	    const problems = [];
222	
223	    const title = titleInput.value.trim();
224	    if (!title) {
225	      titleInput.classList.add("invalid");
226	      titleErr.textContent = "标题不能为空。";
227	      problems.push({el: titleInput, msg: "问卷标题不能为空。"});
228	    }
229	
230	    const cards = [...qBox.querySelectorAll(".q-card")];
231	    if (cards.length === 0) {
232	      qErr.textContent = "问卷至少需要保留一道题。";
233	      problems.push({el: qBox, msg: "问卷至少需要保留一道题，请先添加题目。"});
234	    }
235	
236	    const payloadQuestions = [];
237	    cards.forEach((card, i) => {
238	      const loc = `第 ${i + 1} 题`;
239	      const titleEl = card.querySelector(".q-title");
240	      const qTitle = titleEl.value.trim();
241	      if (!qTitle) {
242	        titleEl.classList.add("invalid");
243	        card.querySelector(".q-title-err").textContent = `${loc}：题目标题不能为空。`;
244	        problems.push({el: titleEl, msg: `${loc}：题目标题不能为空。`});
245	      }
246	      const q = {
247	        type: card.dataset.type,
248	        title: qTitle,
249	        required: card.querySelector(".q-required").checked
250	      };
251	      if (card.dataset.type === "single_choice") {
252	        const optInputs = [...card.querySelectorAll(".opt-text")];
253	        const values = optInputs.map(el => el.value.trim());
254	        const optErr = card.querySelector(".opt-err");
255	        const seen = new Set();
256	        values.forEach((val, j) => {
257	          if (!val) {
258	            optInputs[j].classList.add("invalid");
259	            optErr.textContent = `${loc}：第 ${j + 1} 个选项不能为空。`;
260	            problems.push({el: optInputs[j], msg: `${loc}：第 ${j + 1} 个选项不能为空。`});
261	          } else if (seen.has(val)) {
262	            optInputs[j].classList.add("invalid");
263	            optErr.textContent = `${loc}：选项“${val}”与同题其他选项重复。`;
264	            problems.push({el: optInputs[j], msg: `${loc}：选项“${val}”重复。`});
265	          }
266	          seen.add(val);
267	        });
268	        if (values.length < 2) {
269	          optErr.textContent = `${loc}：单选题至少需要两个选项。`;
270	          problems.push({el: card.querySelector(".add-opt"), msg: `${loc}：单选题至少需要两个选项。`});
271	        }
272	        q.options = values;
273	      }
274	      payloadQuestions.push(q);
275	    });
276	
277	    if (problems.length) {
278	      showBanner(problems);
279	      return;
280	    }
281	
282	    const payload = {title, description: descArea.value, questions: payloadQuestions};
283	    const endpoint = mode === "edit" ? `/api/surveys/${existing.id}` : "/api/surveys";
284	    let resp;
285	    try {
286	      resp = await fetch(endpoint, {
287	        method: mode === "edit" ? "PUT" : "POST",
288	        headers: {"Content-Type": "application/json"},
289	        body: JSON.stringify(payload)
290	      });
291	    } catch (err) {
292	      // 请求未成功：保留当前全部输入与增删结果
293	      showBanner([{el: null, msg: `网络错误，问卷尚未保存：${err}`}]);
294	      return;
295	    }
296	    let data = {};
297	    try { data = await resp.json(); } catch (_) { /* 保留已输入内容 */ }
298	    const saved = mode === "edit" ? resp.status === 200 : resp.status === 201;
299	    if (saved && data.id !== undefined) {
300	      if (mode === "create") {
301	        form.reset();
302	        qBox.replaceChildren();
303	        if (hooks && hooks.onCreated) hooks.onCreated();
304	      }
305	      location.hash = `#/surveys/${data.id}`;
306	      return;
307	    }
308	    // 服务端未确认保存成功：不清空任何输入，展示具体问题
309	    showBanner([{el: null, msg: data.error || `保存失败（HTTP ${resp.status}），问卷未保存，请检查后重试。`}]);
310	  }
311	
312	  return form;
313	}
314	
315	/* ---------- 首页 ---------- */
316	
317	function renderHome() {
318	  const view = ++activeView;
319	  app.replaceChildren();
320	
321	  const listSection = h("section", null,
322	    h("h2", null, "问卷列表"),
323	    h("ul", {class: "plain", id: "survey-list"}, h("li", {class: "muted"}, "加载中…"))
324	  );
325	  const listEl = listSection.querySelector("#survey-list");
326	
327	  async function loadSurveys() {
328	    let data;
329	    try {
330	      const resp = await fetch("/api/surveys");
331	      data = await resp.json();
332	    } catch (err) {
333	      if (view !== activeView) return;
334	      listEl.replaceChildren(h("li", {class: "muted"}, "问卷列表加载失败。"));
335	      return;
336	    }
337	    if (view !== activeView) return;
338	    listEl.replaceChildren();
339	    if (!data.surveys.length) {
340	      listEl.append(h("li", {class: "muted"}, "还没有问卷记录。"));
341	      return;
342	    }
343	    for (const survey of data.surveys) {
344	      listEl.append(h("li", null,
345	        h("a", {href: `#/surveys/${survey.id}`}, `#${survey.id} ${survey.title}`)));
346	    }
347	  }
348	
349	  app.append(
350	    listSection,
351	    buildSurveyForm(null, {onCreated: loadSurveys})
352	  );
353	  loadSurveys();
354	}
355	
356	/* ---------- 问卷详情 ---------- */
357	
358	async function renderDetail(id) {
359	  const view = ++activeView;
360	  app.replaceChildren(
361	    h("p", null, h("a", {href: "#/"}, "← 返回首页")),
362	    h("p", {class: "muted", id: "detail-status"}, "加载中…")
363	  );
364	  const status = document.getElementById("detail-status");
365	
366	  let survey;
367	  try {
368	    const resp = await fetch(`/api/surveys/${id}`);
369	    if (view !== activeView) return;
370	    if (resp.status === 404) {
371	      status.textContent = `问卷 #${id} 不存在。`;
372	      return;
373	    }
374	    if (!resp.ok) {
375	      status.textContent = `详情加载失败（HTTP ${resp.status}），请稍后重试。`;
376	      return;
377	    }
378	    survey = await resp.json();
379	  } catch (err) {
380	    if (view !== activeView) return;
381	    status.textContent = `详情加载失败：${err}`;
382	    return;
383	  }
384	  if (view !== activeView) return;
385	
386	  app.replaceChildren(
387	    h("p", null, h("a", {href: "#/"}, "← 返回首页")),
388	    h("h2", null, `#${survey.id} ${survey.title}`),
389	    h("div", {class: "row-actions"},
390	      h("a", {class: "btn", href: `#/surveys/${survey.id}/edit`}, "编辑草稿"),
391	      h("a", {class: "btn secondary", href: "#/"}, "返回首页")
392	    ),
393	    h("h3", null, "说明"),
394	    survey.description
395	      ? h("p", {class: "detail-desc"}, survey.description)
396	      : h("p", {class: "muted"}, "（无说明）"),
397	    h("h3", null, `题目（共 ${survey.questions.length} 道）`)
398	  );
399	  if (!survey.questions.length) {
400	    app.append(
401	      h("p", {class: "muted"}, "该问卷草稿还没有题目，可进入编辑补齐。"),
402	      h("p", null, h("a", {class: "btn", href: `#/surveys/${survey.id}/edit`}, "编辑草稿并添加题目"))
403	    );
404	    return;
405	  }
406	  app.append(h("ol", {class: "q-list"},
407	    survey.questions.map((q, i) => h("li", null,
408	      h("div", {class: "q-line"},
409	        `${i + 1}. ${q.title} `,
410	        h("span", {class: "tag"}, q.type === "single_choice" ? "单选题" : "文本题"),
411	        " ",
412	        h("span", {class: "tag" + (q.required ? " required" : "")}, q.required ? "必填" : "选填")
413	      ),
414	      q.options && q.options.length
415	        ? h("ol", {start: "1"}, q.options.map(opt => h("li", {class: "opt-text-display"}, opt)))
416	        : null
417	    )))
418	  );
419	}
420	
421	/* ---------- 编辑草稿 ---------- */
422	
423	function showEditLoadError(id, message, view) {
424	  // 加载失败时明确提示，绝不能用空白编辑表单覆盖已有内容
425	  if (view !== activeView) return;
426	  app.replaceChildren(
427	    h("p", null, h("a", {href: "#/"}, "← 返回首页")),
428	    h("h2", null, `编辑问卷草稿 #${id}`),
429	    h("div", {class: "banner", role: "alert"},
430	      h("strong", null, "问卷内容加载失败，未打开编辑表单："),
431	      h("p", {class: "detail-meta", style: "margin:.4rem 0 0"}, message),
432	      h("p", {style: "margin:.6rem 0 0"},
433	        h("button", {type: "button", class: "btn secondary", onclick: () => renderEdit(id)}, "重试"), " ",
434	        h("a", {class: "btn secondary", href: `#/surveys/${id}`}, "返回详情"))
435	    )
436	  );
437	}
438	
439	async function renderEdit(id) {
440	  const view = ++activeView;
441	  app.replaceChildren(
442	    h("p", null, h("a", {href: `#/surveys/${id}`}, "← 返回问卷详情")),
443	    h("p", {class: "muted", id: "edit-status"}, "加载中…")
444	  );
445	
446	  let survey;
447	  try {
448	    const resp = await fetch(`/api/surveys/${id}`);
449	    if (view !== activeView) return;
450	    if (resp.status === 404) {
451	      showEditLoadError(id, `问卷 #${id} 不存在。`, view);
452	      return;
453	    }
454	    if (!resp.ok) {
455	      showEditLoadError(id, `服务端返回异常（HTTP ${resp.status}），请稍后重试。`, view);
456	      return;
457	    }
458	    survey = await resp.json();
459	  } catch (err) {
460	    showEditLoadError(id, `网络错误：${err}。已保存的问卷内容未受影响，可重试加载。`, view);
461	    return;
462	  }
463	
464	  if (view !== activeView) return;
465	  app.replaceChildren(
466	    h("p", null, h("a", {href: `#/surveys/${id}`}, "← 返回问卷详情")),
467	    buildSurveyForm(survey, {})
468	  );
469	}
470	
471	function route() {
472	  const editMatch = location.hash.match(/^#\/surveys\/(\d+)\/edit$/);
473	  const detailMatch = location.hash.match(/^#\/surveys\/(\d+)$/);
474	  if (editMatch) renderEdit(Number(editMatch[1]));
475	  else if (detailMatch) renderDetail(Number(detailMatch[1]));
476	  else renderHome();
477	}
478	window.addEventListener("hashchange", route);
479	route();
480	</script>
481	</html>
482	"""
483	
484	
485	def validate_survey(obj):
486	    """Validate a decoded survey payload.
487	
488	    Returns (clean_survey, None) on success or (None, error_message) on failure.
489	    Strings are stored trimmed of surrounding whitespace; description keeps its
490	    raw value so Chinese, quotes and newlines are preserved.
491	    """
492	    if not isinstance(obj, dict):
493	        return None, "请求体必须是 JSON 对象"
494	    if "title" not in obj:
495	        return None, "缺少字段 title"
496	    title = obj["title"]
497	    if not isinstance(title, str):
498	        return None, "title 必须是字符串"
499	    title = title.strip()
500	    if not title:
501	        return None, "title 不能为空（或全为空白字符）"
502	
503	    description = obj.get("description", "")
504	    if not isinstance(description, str):
505	        return None, "description 必须是字符串"
506	
507	    if "questions" not in obj:
508	        return None, "缺少字段 questions"
509	    raw_questions = obj["questions"]
510	    if not isinstance(raw_questions, list):
511	        return None, "questions 必须是数组"
512	    if len(raw_questions) == 0:
513	        return None, "questions 至少需要一道题"
514	
515	    questions = []
516	    for index, raw_question in enumerate(raw_questions, start=1):
517	        location = f"第 {index} 题"
518	        if not isinstance(raw_question, dict):
519	            return None, f"{location}（questions[{index - 1}]）必须是对象"
520	
521	        if "type" not in raw_question:
522	            return None, f"{location}：缺少字段 type"
523	        question_type = raw_question["type"]
524	        if not isinstance(question_type, str):
525	            return None, f"{location}：type 必须是字符串"
526	        if question_type not in QUESTION_TYPES:
527	            shown = json.dumps(question_type, ensure_ascii=False)
528	            return None, f"{location}：不支持的题型 {shown}（仅支持 text 或 single_choice）"
529	
530	        if "title" not in raw_question:
531	            return None, f"{location}：缺少字段 title"
532	        question_title = raw_question["title"]
533	        if not isinstance(question_title, str):
534	            return None, f"{location}：title 必须是字符串"
535	        question_title = question_title.strip()
536	        if not question_title:
537	            return None, f"{location}：题目标题不能为空（或全为空白字符）"
538	
539	        required = raw_question.get("required", False)
540	        if not isinstance(required, bool):
541	            return None, f"{location}：required 必须是布尔值"
542	
543	        raw_options = raw_question.get("options", [])
544	        if not isinstance(raw_options, list):
545	            return None, f"{location}：options 必须是数组"
546	
547	        options = []
548	        if question_type == "text":
549	            if len(raw_options) > 0:
550	                return None, f"{location}：文本题不能包含选项（options 必须省略或为空数组）"
551	        else:
552	            if len(raw_options) < 2:
553	                return None, f"{location}：单选题至少需要两个选项"
554	            seen = set()
555	            for option_index, raw_option in enumerate(raw_options, start=1):
556	                if not isinstance(raw_option, str):
557	                    return None, f"{location}：第 {option_index} 个选项必须是字符串"
558	                option = raw_option.strip()
559	                if not option:
560	                    return None, f"{location}：第 {option_index} 个选项不能为空（或全为空白字符）"
561	                if option in seen:
562	                    shown = json.dumps(option, ensure_ascii=False)
563	                    return None, f"{location}：选项 {shown} 重复（同一题内选项不得重复）"
564	                seen.add(option)
565	                options.append(option)
566	
567	        questions.append({
568	            "type": question_type,
569	            "title": question_title,
570	            "required": required,
571	            "options": options,
572	        })
573	
574	    return {
575	        "title": title,
576	        "description": description,
577	        "questions": questions,
578	    }, None
579	
580	
581	def main():
582	    parser = argparse.ArgumentParser(description="OpenSurvey - 问卷调查与反馈管理")
583	    commands = parser.add_subparsers(dest="command", required=True)
584	    serve = commands.add_parser("serve", help="Start the HTTP service")
585	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
586	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
587	    serve.add_argument("--data-dir", type=Path, default=Path("data"), help="Directory for the local SQLite database")
588	    args = parser.parse_args()
589	    if not 0 <= args.port <= 65535:
590	        parser.error("port must be between 0 and 65535")
591	    args.data_dir.mkdir(parents=True, exist_ok=True)
592	    database = sqlite3.connect(args.data_dir / "open-survey.sqlite")
593	    database.execute("CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY, title TEXT NOT NULL)")
594	    columns = {row[1] for row in database.execute("PRAGMA table_info(surveys)")}
595	    if "description" not in columns:
596	        database.execute("ALTER TABLE surveys ADD COLUMN description TEXT NOT NULL DEFAULT ''")
597	    database.execute(
598	        "CREATE TABLE IF NOT EXISTS questions ("
599	        "id INTEGER PRIMARY KEY, survey_id INTEGER NOT NULL, position INTEGER NOT NULL, "
600	        "type TEXT NOT NULL, title TEXT NOT NULL, required INTEGER NOT NULL)"
601	    )
602	    database.execute(
603	        "CREATE TABLE IF NOT EXISTS question_options ("
604	        "id INTEGER PRIMARY KEY, question_id INTEGER NOT NULL, position INTEGER NOT NULL, text TEXT NOT NULL)"
605	    )
606	    database.commit()
607	
608	    def survey_detail(survey_id):
609	        row = database.execute(
610	            "SELECT title, COALESCE(description, '') FROM surveys WHERE id = ?",
611	            (survey_id,),
612	        ).fetchone()
613	        if row is None:
614	            return None
615	        title, description = row
616	        questions = []
617	        question_rows = database.execute(
618	            "SELECT id, type, title, required FROM questions WHERE survey_id = ? ORDER BY position",
619	            (survey_id,),
620	        ).fetchall()
621	        for question_id, question_type, question_title, required in question_rows:
622	            options = [option_row[0] for option_row in database.execute(
623	                "SELECT text FROM question_options WHERE question_id = ? ORDER BY position",
624	                (question_id,),
625	            )]
626	            questions.append({
627	                "type": question_type,
628	                "title": question_title,
629	                "required": bool(required),
630	                "options": options,
631	            })
632	        return {
633	            "id": survey_id,
634	            "title": title,
635	            "description": description,
636	            "questions": questions,
637	        }
638	
639	    def save_survey(clean):
640	        """Insert the whole survey atomically; returns the new id."""
641	        try:
642	            cursor = database.execute(
643	                "INSERT INTO surveys (title, description) VALUES (?, ?)",
644	                (clean["title"], clean["description"]),
645	            )
646	            survey_id = cursor.lastrowid
647	            write_questions(survey_id, clean["questions"])
648	            database.commit()
649	            return survey_id
650	        except Exception:
651	            database.rollback()
652	            raise
653	
654	    def write_questions(survey_id, questions):
655	        """Replace all questions/options of a survey with the given ordered list."""
656	        old_question_ids = [row[0] for row in database.execute(
657	            "SELECT id FROM questions WHERE survey_id = ?", (survey_id,)
658	        )]
659	        if old_question_ids:
660	            placeholders = ",".join("?" for _ in old_question_ids)
661	            database.execute(
662	                f"DELETE FROM question_options WHERE question_id IN ({placeholders})",
663	                old_question_ids,
664	            )
665	        database.execute("DELETE FROM questions WHERE survey_id = ?", (survey_id,))
666	        for position, question in enumerate(questions):
667	            question_cursor = database.execute(
668	                "INSERT INTO questions (survey_id, position, type, title, required) "
669	                "VALUES (?, ?, ?, ?, ?)",
670	                (survey_id, position, question["type"], question["title"],
671	                 1 if question["required"] else 0),
672	            )
673	            question_id = question_cursor.lastrowid
674	            for option_position, option in enumerate(question["options"]):
675	                database.execute(
676	                    "INSERT INTO question_options (question_id, position, text) VALUES (?, ?, ?)",
677	                    (question_id, option_position, option),
678	                )
679	
680	    def replace_survey(survey_id, clean):
681	        """Replace a whole survey atomically; keeps the same id.
682	
683	        Returns False when the survey does not exist (no record is created).
684	        """
685	        row = database.execute("SELECT 1 FROM surveys WHERE id = ?", (survey_id,)).fetchone()
686	        if row is None:
687	            return False
688	        try:
689	            database.execute(
690	                "UPDATE surveys SET title = ?, description = ? WHERE id = ?",
691	                (clean["title"], clean["description"], survey_id),
692	            )
693	            write_questions(survey_id, clean["questions"])
694	            database.commit()
695	            return True
696	        except Exception:
697	            database.rollback()
698	            raise
699	
700	    class Handler(BaseHTTPRequestHandler):
701	        def respond(self, status, value, *, html=False, allow=None):
702	            payload = value.encode("utf8") if html else json.dumps(value, ensure_ascii=False).encode("utf8")
703	            self.send_response(status)
704	            self.send_header("Content-Type", "text/html; charset=utf-8" if html else "application/json; charset=utf-8")
705	            self.send_header("Content-Length", str(len(payload)))
706	            if status == 405 and allow is not None:
707	                self.send_header("Allow", ", ".join(allow))
708	            self.end_headers()
709	            self.wfile.write(payload)
710	
711	        def list_surveys(self):
712	            records = [
713	                {"id": row[0], "title": row[1]}
714	                for row in database.execute("SELECT id, title FROM surveys ORDER BY id")
715	            ]
716	            self.respond(200, {RESOURCE: records})
717	
718	        def read_payload(self):
719	            """Read and decode a JSON request body.
720	
721	            Returns (payload, None) or (None, error_message).
722	            """
723	            try:
724	                length = int(self.headers.get("Content-Length") or 0)
725	            except ValueError:
726	                length = -1
727	            if length < 0:
728	                return None, "Content-Length 无效"
729	            if length > MAX_BODY_BYTES:
730	                return None, "请求体过大"
731	            body = self.rfile.read(length) if length else b""
732	            try:
733	                return json.loads(body.decode("utf8")), None
734	            except (UnicodeDecodeError, json.JSONDecodeError) as error:
735	                return None, f"请求体不是合法 JSON：{error}"
736	
737	        def create_survey(self):
738	            payload, error = self.read_payload()
739	            if error is not None:
740	                self.respond(400, {"error": error})
741	                return
742	
743	            clean, error = validate_survey(payload)
744	            if error is not None:
745	                self.respond(400, {"error": error})
746	                return
747	            try:
748	                survey_id = save_survey(clean)
749	            except sqlite3.DatabaseError as error:
750	                self.respond(500, {"error": f"保存失败：{error}"})
751	                return
752	            result = {"id": survey_id, **clean}
753	            self.respond(201, result)
754	
755	        def update_survey(self, survey_id):
756	            payload, read_error = self.read_payload()
757	            if survey_detail(survey_id) is None:
758	                # Editing a missing id is always 404 and must never create one.
759	                self.respond(404, {"error": "not found"})
760	                return
761	            if read_error is not None:
762	                self.respond(400, {"error": read_error})
763	                return
764	
765	            # Full replacement: validate before touching the stored draft so a
766	            # rejected request leaves the old survey exactly as it was.
767	            clean, error = validate_survey(payload)
768	            if error is not None:
769	                self.respond(400, {"error": error})
770	                return
771	            try:
772	                replace_survey(survey_id, clean)
773	            except sqlite3.DatabaseError as error:
774	                self.respond(500, {"error": f"保存失败：{error}"})
775	                return
776	            self.respond(200, {"id": survey_id, **clean})
777	
778	        def route(self):
779	            location = urlsplit(self.path).path
780	            detail_match = re.fullmatch(r"/api/surveys/(\d+)", location)
781	
782	            if location == "/api/surveys":
783	                allowed = ["GET", "POST"]
784	            elif location in ("/", "/health"):
785	                allowed = ["GET"]
786	            elif detail_match:
787	                allowed = ["GET", "PUT"]
788	            else:
789	                self.respond(404, {"error": "not found"})
790	                return
791	
792	            if self.command not in allowed:
793	                self.respond(405, {"error": "method not allowed"}, allow=allowed)
794	                return
795	
796	            if location == "/":
797	                self.respond(200, PAGE, html=True)
798	            elif location == "/health":
799	                self.respond(200, {"status": "ok", "product": PRODUCT})
800	            elif location == "/api/surveys":
801	                if self.command == "POST":
802	                    self.create_survey()
803	                else:
804	                    self.list_surveys()
805	            else:
806	                survey_id = int(detail_match.group(1))
807	                if self.command == "PUT":
808	                    self.update_survey(survey_id)
809	                    return
810	                detail = survey_detail(survey_id)
811	                if detail is None:
812	                    self.respond(404, {"error": "not found"})
813	                else:
814	                    self.respond(200, detail)
815	
816	        do_GET = do_POST = do_PUT = do_PATCH = do_DELETE = do_HEAD = do_OPTIONS = route
817	
818	    def stop(_signal, _frame):
819	        raise KeyboardInterrupt
820	
821	    signal.signal(signal.SIGTERM, stop)
822	    server = None
823	    try:
824	        server = HTTPServer((args.host, args.port), Handler)
825	        host, port = server.server_address[:2]
826	        address = f"[{host}]" if ":" in host else host
827	        print(f"{PRODUCT} listening on http://{address}:{port}", flush=True)
828	        server.serve_forever()
829	    except KeyboardInterrupt:
830	        pass
831	    finally:
832	        if server is not None:
833	            server.server_close()
834	        database.close()
835	
836	
837	if __name__ == "__main__":
838	    main()
